def countFibSums(n):
    fibs = [1, 2]
    while fibs[-1] + fibs[-2] <= n:
        fibs.append(fibs[-1] + fibs[-2])
    pre = [0]
    for f in fibs:
        pre.append(pre[-1] + f)
    memo = {}

    def count(i, r):
        if r == 0:
            return 1
        if i == 0 or r > pre[i]:
            return 0
        key = (i, r)
        if key in memo:
            return memo[key]
        res = count(i - 1, r)
        if r >= fibs[i - 1]:
            res += count(i - 1, r - fibs[i - 1])
        memo[key] = res
        return res

    return count(len(fibs), n)
